// Trio icons, EXACT-USE (boss 2026-10-27 18:28: "এগুলোই হুবহু ইউজ করতে
// বলেছি"). Sliced from the boss's own crop (1000225032_1_evo7.jpg) into
// transparent PNGs, embedded here as data URIs — NOT redrawn SVGs (round 3's
// redraws were rejected as substitutes), NOT Feather. Why data URIs, not
// require() PNG files: the GitHub connector's snapshot push accepts UTF-8
// files ONLY and rejects binary contents, so PNG files cannot reach the repo
// through our only push route — data URIs keep the exact pixels in a
// pushable UTF-8 module, and OTA bundles carry them with zero asset-manifest
// risk (they decode at runtime). Black glyph + transparent bg; the screen
// recolors via tintColor per theme (dark on light, light on dark).
export const TRIO_DOTS = 'data:image/png;base64,';
export const TRIO_SHARE = 'data:image/png;base64,';
export const TRIO_X = 'data:image/png;base64,';
